const land=n=>PN[n].adj.filter(m=>!SEA.has(n+"-"+m)&&!SEA.has(m+"-"+n));
const NDIST={};const ndist=a=>{if(NDIST[a])return NDIST[a];const d={[a]:0},q=[a];while(q.length){const c=q.shift();PN[c].adj.forEach(n=>{if(d[n]==null){d[n]=d[c]+1;q.push(n)}})}return NDIST[a]=d};
const PAT=["quiz","lucky","quiz","shop","quiz","bad","card","quiz"];
const RNAME=r=>r==="all"||r==null?"全国":REGIONS[r];
